# Q14: add the chemistry-contrast results to /output/report.json and mark the superseded CH3OH statements (idempotent: removes earlier Q14 entries first)
import json
p='/output/report.json'; r=json.load(open(p))
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q14')]
r['recipe']=[x for x in r['recipe'] if not x['description'].startswith('Q14')]
r['caveats']=[x for x in r['caveats'] if not x.startswith('Q14')]
i=r['interpretation'].find('\n\nQ14:')
if i>=0: r['interpretation']=r['interpretation'][:i]
REV="[REVISED in Q14: see the Q14 CH3OH entries; the Trot~9 K constraint, the chi2=53/6 Q-branch excess and the Band-5 blend integral of this entry are baseline-limited (blend integral 0.9-1.9 K km/s over L/Q/R baselines; p0001 value = linear-baseline end), not established.] "
for x in r['results']:
    q=x['quantity']
    if q.startswith('Matched-beam CH3OH comparison at the Band-5 peak pixel') or q.startswith('Q4: CH3OH Band-5 Q-branch excess') or q.startswith('Q4b: CH3OH N/S limits reconciled'):
        if not x['value'].startswith('[REVISED'): x['value']=REV+x['value']; x['confidence']='low'
A=lambda n,v:{"name":n,"value":v}
common=[A("regions","out/regions.csv: N (0,+2.55\"), S (-0.15,-2.55\"), Bridge (+0.30,+0.15\"), Wclump (-1.8,-2.4\"), Soutflow (-0.15,-4.5\"); values at the position (bilinear) of cubes convolved channel-wise to the stated beam"),
 A("intensity","K km/s = Rayleigh-Jeans Tb; pbcor cubes; Gaussian at v0,FWHM of HCO+ in the same beam/region + linear baseline in +-450 km/s; error = residual rms (robust) x1.3 (channel-correlation inflation, assumption)"),
 A("redshift","rest frequencies at vsys 2780 km/s (radio, LSRK); CDMS/JPL/LAMDA values")]
def R(q,v,u,unit,conf,ev,tgt,extra=()):
    r['results'].append({"quantity":q,"value":v,"uncertainty":u,"unit":unit,"confidence":conf,"evidence":ev,"target":tgt,"assumptions":common+list(extra)})
R("Q14a: CH3OH 2(0)-1(-1)E (254.015 GHz) / HCO+ 3-2 versus beam and region (same-beam ratio of K km/s; N, S, Bridge, W clump, S-outflow lobe)",
 "Xb4d @1.05\": N -0.0002+-0.0047, S 0.0044+-0.0053 (3 sigma limits <0.014, <0.020), Bridge 0.0485+-0.0047, Wclump 0.059+-0.007, Soutflow <0.19. Xb4d @1.7\": N 0.0040+-0.0024, S 0.0082+-0.0041, Bridge 0.0374+-0.0037, Wclump 0.0379+-0.0048. Xb4d @4.45x2.95\": N 0.0057+-0.0022 (2.6 sigma), S 0.0177+-0.0033, Bridge 0.0198+-0.0029, Wclump 0.0243+-0.0030, Soutflow 0.0158+-0.0103. Xb4d @6.3x3.8\": N 0.0048+-0.0023, S 0.0190+-0.0032, Bridge 0.0160+-0.0021, W 0.0229+-0.0027, Soutflow 0.0184+-0.0061. Xb4f @6.3x3.8\": N 0.0056+-0.0027, S 0.0252+-0.0034, Bridge 0.0173+-0.0032, W 0.0289+-0.0028, Soutflow 0.0274+-0.0080 (3.4 sigma). The S value grows 6x from 1.05\" to 6\" (CH3OH is extended, not S-nuclear) while the Bridge/W clump signal is compact (0.05 at 1\") and dilutes to 0.017-0.029; N stays <~0.006 at all beams. S - N at 6.3x3.8\" (Xb4f) = 0.0196+-0.0043 (4.6 sigma), Xb4d 4.45\": 3.0 sigma, 1.7\": 0.9 sigma. Disk (Xb55 mask): blend/HCO+ 2-1 -0.009+-0.006, 3 sigma <0.017.",
 "+-(0.002-0.01) statistical (x1.3 inflated); Xb4d vs Xb4f recovery (CH3OH 55-77% vs HCO+ 83-88%) is the beam/array systematic","ratio","medium","scripts/q14a_beamseq.py -> out/q14/beamseq.csv, beamseq_lines.csv; scripts/q14d_disk.py -> out/q14/disk_limits.csv","N, S, Bridge, Wclump, Soutflow, Disk",
 [A("reconciliation with team-b","our earlier N<0.013/S<0.017 (0.95\", no error inflation) become <0.014/<0.020 with the x1.3 inflation; team-b p0002 (<0.02/<0.03, fixed-window moment-0, no template) and p0016 (4.3x2.8\" deblended N+S+Bridge: N<0.022, S 0.011+-0.006) use noisier estimators / a different beam; our 4.45x2.95\" S 0.0177+-0.0033 differs from their 0.011+-0.006 by 1 sigma and N 0.0057+-0.0022 is below their limit: no conflict. Bridge 0.0485+-0.0047 vs team-b 0.042+-0.012")])
R("Q14b: CH3OH Band-5 Q-branch blend with an explicit spw22 edge-ramp baseline: ramp amplitude, blend integral, baseline systematic",
 "Negative ramp at the low-frequency edge of Xb55 spw22: mean of the first 30 channels -2.3/-3.3/-3.7/-3.2 mJy/beam at N/S/Bridge/W (rms 2.3-2.5 per 1.95 MHz channel), = -0.16/-0.27/-0.25/-0.27 x the 1.2 mm-band continuum at that pixel (14.1/12.4/14.8/12.0 mJy/beam); independent reproduction of team-b p0020 (-0.16 to -0.21). Blend (J=1-3, +-245 km/s) integrals in K km/s for baselines L (linear), Q (quadratic), R (linear + exp ramp): N 1.28/0.99/0.45, S 1.56/0.79/0.84, Bridge 1.86/1.11/0.88, W 1.72/1.34/1.04; mean +- stat +- sys(half-range): N 0.91+-0.09+-0.42, S 1.06+-0.10+-0.39, Bridge 1.28+-0.10+-0.49, W 1.36+-0.10+-0.34 K km/s (= 1.18, 1.38, 1.67, 1.77 Jy/beam km/s; team-b p0020: 1.13, 1.61, 1.69, 0.72). The p0001 phase-centre value 1.71 K km/s sits at the linear-baseline end (Bridge L 1.86), 1.3-2x above the R/Q baselines. Blend / HCO+ 2-1 at the Xb55 beam: N 0.029, S 0.035, Bridge 0.036, W 0.045 (sys +-35-45%): no N/S/Bridge contrast.",
 "sys 30-45% (baseline shape under the line is extrapolated; R, Q, L differ up to 2x); stat 0.09-0.10 K km/s","K km/s","low","scripts/q14b_ch3oh_blend.py -> out/q14/ramp_continuum.csv, blend_integrals.csv","N, S, Bridge, Wclump (Xb55 beam 9.36x6.28\")",
 [A("baselines","anchors outside +-(200+120) km/s of the blend and +-250 km/s of Q J=4,5,6; R fitted over 163.53+-0.9 GHz with tau grid 15-130 channels (best 130 = grid edge)"),A("beam","Xb55 native 9.36x6.28\" (pixel 1.2\"), N/S/Bridge only 5\" apart, so the regions overlap in this beam")])
R("Q14c: CH3OH rotation temperature from the 254 GHz line (Xb4f smoothed to the Xb55 beam) over the Q-branch blend, thin LTE, baseline systematic propagated (replaces Trot~9 K of p0001)",
 "R=I(254)/I(blend): N 0.12 (0.09-0.20; 254 line 4.2 sigma), S 0.31 (0.22-0.37), Bridge 0.19 (0.14-0.24), W 0.24 (0.20-0.29). Trot (median, 68% [2.5-97.5%]): S 10.9 (8.1-15.2) K [6.5-21.9], W clump 13.4 (10.2-18.1) K [8.4-25.3], Bridge 22.9 (13.2-57.7) K [9.6, unbounded], N unconstrained (T16 = 19 K, 57% of draws >60 K). LTE R(T)=0.51, 0.30, 0.22, 0.19, 0.16 at 6, 10, 15, 20, 30 K. Agrees with team-b p0020 (S 13 (10-20) K). CH3OH is cold or unconstrained everywhere (S, W <~25 K at 97.5%), and no region needs Trot>~20 K except possibly the Bridge/N.",
 "see value (flat prior 4-60 K; baseline uniform between min and max of L/Q/R plus stat; 254 error x1.3)","K","low","scripts/q14b_ch3oh_blend.py -> out/q14/trot.csv","S, W clump, Bridge, N",
 [A("LTE","thin, single Trot, Bose/background-corrected line strengths nu S mu2 exp(-Eu/T) with Tbg=2.73 K, E-type only (254 and the Q-branch are both E)"),A("beam","254 GHz line smoothed to the Xb55 beam; N, S, Bridge overlap")])
R("Q14d: beam-averaged CH3OH column densities (thin LTE from the 254 GHz line at the Xb55 beam) and thin-LTE ratios N(X)/N(HCO+)",
 "N_u(2_0 E): N 7.2e11, S 2.1e12, Bridge 1.6e12, W 2.2e12 cm-2 (Xb55 beam). N(E-CH3OH) at Trot 10/20/30 K (x1e13): S 2.9/4.4/6.6; Bridge 2.2/3.3/4.9; W 2.9/4.4/6.6; N 0.97/1.5/2.2; N(A+E) = N(E) x 2.4/2.1/2.0 from the LAMDA A-file partition function (all in out/q14/blend_integrals.csv). At the Xb4f 6.3x3.8\" beam N(CH3OH)/N_thin(HCO+) at Tex(both)=10/20/30 K: N 1.1/3.2/4.9, S 5.0/14/22, Bridge 3.4/9.7/15, W 5.7/16/25; because HCO+ 3-2 is optically thick (tau32 ~6-30, Q2/q4c) these must be divided by 6-30 to estimate true column ratios: CH3OH/HCO+ ~ 0.1-2 at S, 0.04-0.5 at N; they depend on Tex(CH3OH) more than on anything else (x3 per 10 K). Equal-Tex S/N column contrast 4.5; if T_N=30 K and T_S=10 K (Q2: N warmer) it drops to 1.0.",
 "factor ~3 from Tex(CH3OH), ~6-30 from HCO+ opacity, filling factors assumed equal; not an abundance (no N(H2))","cm-2 / ratio","low","scripts/q14b_ch3oh_blend.py, scripts/q14c_columns.py -> out/q14/blend_integrals.csv, columns.csv","S, Bridge, W, N",
 [A("partition functions","E and A CH3OH ladders from LAMDA e-ch3oh.dat/ch3oh_a.dat (levels to 976 K), LTE ortho:para = Boltzmann; HCO+ Q from hco+.dat"),A("tau(HCO+ 3-2)","6-30 from the Q2/q4c RADEX posteriors (not re-derived)")])
R("Q14e: CS 7-6 / HCO+ 4-3 and / HCN 4-3 by region at matched beams (Xb47, beam 4.45x2.95\" and 6.3x3.8\"); N/S double ratio and what it means",
 "CS 7-6/HCO+ 4-3 @4.45x2.95\": N 0.092+-0.005, S 0.044+-0.006, Bridge 0.043+-0.008, W 0.042+-0.005, Soutflow 0.031+-0.015; @6.3x3.8\": N 0.080+-0.004, S 0.038+-0.005, Bridge 0.045+-0.005, W 0.037+-0.004, Soutflow 0.038+-0.009 (4 sigma). N/S = 2.10+-0.30 and 2.12+-0.31 (6.5 sigma above 1). CS 7-6/HCN 4-3: N 0.168+-0.009, S 0.152+-0.020 (N/S 1.11+-0.16) at 4.45\"; 0.158/0.137 (1.16+-0.17) at 6.3\": uniform, as in team-b p0016. So the N/S CS/HCO+ contrast is the HCO+ 4-3 (not CS) difference: HCN/HCO+ is lower at S (Q1), CS/HCN is the same. Column interpretation: thin-LTE N(CS)/N(HCO+) from the 7-6/4-3 pair is Tex dependent (N 3.3/1.07/0.74/0.54 at Tex 10/20/30/50 K; S 1.6/0.51/0.35/0.26): N/S = 2.1 at equal Tex but 1.07 for T_N=50 K, T_S=20 K (Q2): no abundance contrast needed. Note the CS 7-6 (Eu 66 K) integral includes H2CS 10(0,10)-9(0,9) (342.944) at <~0.33 K km/s (N) and 29SiO 8-7; the Q1/Q4c deblended CS/HCO+ 3-2 (N 0.051, S 0.056) is a different, deblended definition (team-b reconciliation p0009-r03).",
 "stat as given (x1.3); +-10-20% deblending/aperture (team-b: 20%)","ratio","medium","scripts/q14a_beamseq.py, q14c_columns.py -> out/q14/beamseq.csv, contrasts.csv, columns.csv","N, S, Bridge, W, Soutflow",
 [A("blend","H2CS 10-9 and 29SiO not subtracted (limits only); CS joint fit not repeated")])
R("Q14f: SO, 34SO, HC3N, CH2NH and HOC+ limits/detections relative to HCO+ at matched beams",
 "SO 8_8-7_7/HCO+ 4-3 (Xb47): N 0.011+-0.005 (4.45x2.95\"), 0.008+-0.004 (6.3x3.8\"); S 0.010+-0.007 / 0.010+-0.004; 3 sigma <0.026/0.019 (N), <0.031/0.023 (S), Bridge <0.017/<0.013 (naive template; team-b joint-fit limit <0.011): no SO detection; SO 6_5-5_4 251.826 limits and Trot<12-25 K from Q4b stand (blend with the CH3OH A cluster). Feature at 252.34 GHz sky (rest 254.6995 'HC3N 28-27', Eu 177 K) is blended with CH2NH 4(0,4)-3(0,3) (rest 254.685, Eu 31 K, 17 km/s away): a 'line' detected at N (HC3N+CH2NH/HCO+ 3-2: 0.021+-0.004 at 1.05\", 0.014+-0.003 at 1.7\", 0.0085+-0.0027 at 4.45\"; S, Bridge, W consistent with 0, 3 sigma <0.010-0.026) must be assigned to CH2NH (tentative, 5 sigma, N only) rather than HC3N, whose Eu=177 K makes it implausible in gas with Tex <~50 K: HC3N 28-27 is therefore NOT a constraint (only a limit if CH2NH is assumed absent); Harada's HC3N 10-9 (0.056-0.058 of HCO+ 1-0 at N and S) is not covered by the data. HOC+ 3-2/HCO+ 3-2: N 0.034+-0.004 (1.05\"), 0.030+-0.003 (1.7\"), 0.019-0.027 (6\"), S 0.031+-0.006/0.024+-0.005 (1.05/1.7\") but 0.005-0.012 at 6\", Bridge <0.025 at 1\": tentative (single line, blends not checked beyond Q0). HCN v2=1f 3-2/ground (Q4, Tb, 3 sigma): <0.03 (N, Xb4d), <0.05 (S), i.e. N_vib/N_gnd<0.07 and Tvib<~300-540 K: no hot-core signature.",
 "3 sigma limits, x1.3 error inflation","ratio","low","out/q14/beamseq.csv; out/q4/hcn_vib.csv; out/q4b/so_f_trot.csv","N, S, Bridge, W, Soutflow",
 [A("species not covered","SiO (2-1, 5-4, 6-5, 8-7), HC3N 10-9, CS 2-1, SO 219.949 GHz, CH3OH 96.7 GHz are outside the Band 5/6/7 windows (Harada's Band 3 and 219 GHz lines cannot be remeasured)")])
R("Q14g: comparison with Harada+2018 (ApJ 855, 49; Table 13, 1.7\"): CH3OH/HCO+ 3-2 converted from 254 to 96.74 GHz by thin LTE",
 "LAMDA thin-LTE W(96.74 GHz 2k-1k, A+E sum)/W(254.015) = 6.6, 6.1, 5.5, 5.2, 4.9, 4.6 at Trot 8, 10, 15, 20, 30, 50 K (out/q14/harada_convert.csv). Harada CH3OH(96.74)/HCO+ 3-2: N 0.034+-0.007, S 0.142+-0.015 (S/N 4.2). Predicted from our 254 line at the Xb4f 6.3x3.8\" beam (Trot 8-30 K): N 0.027-0.037 (pred/Harada 0.81-1.09), S 0.123-0.165 (0.86-1.16): agreement. Predicted from Xb4d at 1.7\": N 0.020-0.026 (0.58-0.78), S 0.040-0.054 (0.28-0.38): Xb4d resolves out the extended CH3OH that Harada's ACA-including Band 3 data keep. The CH3OH/HCO+ S/N contrast we measure (4.5+-2.3 at Xb4f 6.3x3.8\", 3.1+-1.3 at Xb4d 4.45\", 2+-1.6 at 1.7\") matches Harada's 4.2 and is the same sense (S > N), but our direct matched-beam test is at 4-6\", not 1.7\", and it depends on Tex (T_N>T_S would shrink it, Q14d). SiO, the other species with the largest variation in Harada, is not in the data. CS: Harada CS 2-1/HCO+ 3-2 N 0.535, S 0.525 (equal); our CS 7-6/HCO+ 4-3 N/S 2.1 is an excitation (Eu 66 K) plus HCO+ 4-3 effect, not a contradiction. Disk: CH3OH undetected, blend/HCO+ 2-1 <0.017 (3 sigma) vs 0.03-0.045 in the nuclei region at the same beam.",
 "pred/Harada 0.8-1.2 at the Xb4f beam; 0.3-0.8 at Xb4d 1.7\"; errors dominated by CH3OH noise 12-50%","ratio","low","scripts/q14c_columns.py -> out/q14/harada_convert.csv, harada_compare.csv, contrasts.csv; out/q4c/harada_ratios.csv","N, S",
 [A("Harada+2018","Table 13 values at 1.7\" (parsed in q4c, out/q4c/harada_table13_rows.csv): taken as published, apertures not re-measured; Harada integrates an aperture, we take the position of the peak"),A("LTE","thin, one Trot for the 96.74 and 254 lines, A:E=1:1 by Boltzmann")])
R("Q14h: summary: chemistry contrast between N, S, Bridge, S-outflow lobe and disk (what the data support)",
 "(1) CH3OH is the only shock-tracer-type species with a detectable, region-dependent signal: CH3OH 254/HCO+ 3-2 is compact and strongest at the Bridge/W clump (0.05-0.06 at 1\"), S > N in the 4-6\" beams (S 0.018-0.025, N 0.005-0.006; S-N 3.0-4.6 sigma), the S-outflow lobe is similar to S (0.016-0.027, 3 sigma), the disk is not detected (<0.017); CH3OH is cold/unconstrained (S 11 [8,15] K, W 13 K, Bridge >~13 K, N unconstrained). The Q-branch 'excess', the Bridge/W 'enhancement' at the Band-5 beam and 'Trot 9 K' of p0001 are not established (baseline-limited). (2) CS 7-6/HCN 4-3 is uniform (0.14-0.17, N/S 1.1+-0.2) in N, S, Bridge, lobe; CS 7-6/HCO+ 4-3 N/S=2.1 is the HCO+ 4-3 difference and is removed by T_N=50, T_S=20 K. (3) SO, 34SO, SiS, HCN v2=1: no detection (SO/HCO+ <0.02-0.03, N_vib/N_gnd<0.07); HC3N 28-27 is blended with CH2NH. (4) Consistent with Harada+2018 for CH3OH (S/N ~4 enhancement, amplitude when beam/recovery matched); SiO untestable. No shock-chemistry signature in the nuclei at 4-6\" resolution; differences between the nuclei, the lobe and the disk are at most factor 3-4 in CH3OH/HCO+ and are not significant for any other species. Ratio-to-HCO+ differences are NOT abundance ratios without Tex and opacity (Q14d).",
 "see items","","low","out/q14/*; scripts/q14a-d","N, S, Bridge, lobe, disk")
r['recipe'].append({"order":max(x['order'] for x in r['recipe'])+1,"stage":"modelling","description":"Q14: (1) q14a_beamseq.py: cubes convolved channel-wise (exact beam-difference kernels) to 1.05\", 1.7\", 4.45x2.95\" (PA 87), 6.3x3.8\" (PA 82), spectra at N,S,Bridge,Wclump,Soutflow; HCO+/HCN: Gaussian+linear fit; other lines: Gaussian template fixed at HCO+ v0,FWHM + linear baseline in +-450 km/s; error x1.3; ratios to HCO+ 3-2 (Xb4d,Xb4f) and HCO+/HCN 4-3 (Xb47); (2) q14b_ch3oh_blend.py: Xb55 spw22 edge-ramp vs continuum, L/Q/R baselines, blend integral, 254/blend Trot Monte Carlo (20000 draws, flat prior 4-60 K), N_u and N(E),N(A+E) from LAMDA partition functions; (3) q14c_columns.py: 96.74 vs 254 GHz LTE conversion for Harada+2018, thin-LTE column ratios, contrasts; (4) q14d_disk.py: disk-stack limit; (5) build_report_q14.py.","scripts":["scripts/q14a_beamseq.py","scripts/q14b_ch3oh_blend.py","scripts/q14c_columns.py","scripts/q14d_disk.py","scripts/build_report_q14.py"]})
r['caveats'].append("Q14: all ratios to HCO+ are line (Tb) ratios, not abundances: Tex (factor ~3 per 10 K for CH3OH, x2 for CS 7-6/4-3) and HCO+ opacity (tau32 6-30) are unconstrained; CH3OH N/S/Bridge excitation rests on one Band-6 line and a Band-5 blend with a 30-45% baseline systematic from the spw22 edge ramp (mechanism inferred, no uv data); Xb4d vs Xb4f CH3OH recovery (55-77%) makes the 1\" N/S limits valid for compact emission only; N and S are separated by <1.3 beams at 4-6\" so the Xb47/Xb4f values are peak-position values including leakage (~10-30%, Q1 deblend); the 252.34 GHz feature is a CH2NH/HC3N blend; SiO, HC3N 10-9, CS 2-1 and SO 219.949 are not covered, so Harada's SiO variation is untested. A second low-Eu CH3OH line at <=4\" and a 1-0/2-1 map at ~1\" would decide the N-vs-S excitation.")
r['interpretation']+="\n\nQ14: Chemistry (third axis of the research question). The data show no shock-chemistry signature that separates the nuclei from each other: CS 7-6/HCN 4-3 is uniform (~0.15), SO, SiS, 34SO and HCN v2=1 are undetected at the 2-3% (of HCO+) level. The one species that varies is CH3OH (cold, Trot ~10-15 K where constrained): relative to HCO+ it is compact and strongest at the Bridge/W clump, extended and S>N (factor ~3-4, 3-4.6 sigma at 4-6\") at the S nucleus, similar in the S-outflow lobe, and absent in the disk (<0.017), which matches Harada+2018 (CH3OH the largest variation, S/N ~4) once the beam and flux recovery are matched. This is a ratio of Tb to HCO+, not an abundance: with equal Tex it is an abundance contrast of ~4, with T_N>T_S as suggested by Q2 it nearly vanishes. Earlier CH3OH claims of p0001 (Trot 9 K, Q-branch excess, Band-5 Bridge enhancement) are withdrawn as baseline-limited."
json.dump(r,open(p,'w'),indent=1)
